{
  "items": [
    {
      "name": "Polynomial.taylor_apply",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (r : R) (f : Polynomial R),\n  (Polynomial.taylor r) f = f.comp (Polynomial.X + Polynomial.C r)"
    },
    {
      "name": "Polynomial.algEquivAevalXAddC_apply",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "theorem",
      "type": "∀ {R : Type u_3} [inst : CommRing R] (t : R) (a : Polynomial R),\n  (Polynomial.algEquivAevalXAddC t) a = (Polynomial.aeval (Polynomial.X + Polynomial.C t)) a"
    },
    {
      "name": "Polynomial.algEquivAevalXAddC",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "definition",
      "type": "{R : Type u_3} → [inst : CommRing R] → R → Polynomial R ≃ₐ[R] Polynomial R"
    },
    {
      "name": "Polynomial.taylor",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → R → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "Polynomial.taylor_taylor",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] (f : Polynomial R) (r s : R),\n  (Polynomial.taylor r) ((Polynomial.taylor s) f) = (Polynomial.taylor (r + s)) f"
    },
    {
      "name": "Polynomial.taylor_X_pow",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (r : R) (n : ℕ),\n  (Polynomial.taylor r) (Polynomial.X ^ n) = (Polynomial.X + Polynomial.C r) ^ n"
    },
    {
      "name": "Polynomial.taylor_X",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (r : R), (Polynomial.taylor r) Polynomial.X = Polynomial.X + Polynomial.C r"
    },
    {
      "name": "Polynomial.map_taylor",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_2} {S : Type u_3} [inst : Semiring R] [inst_1 : Semiring S] (p : Polynomial R) (r : R) (f : R →+* S),\n  Polynomial.map f ((Polynomial.taylor r) p) = (Polynomial.taylor (f r)) (Polynomial.map f p)"
    }
  ]
}
